import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();
        double ratio = (double) x / (double) y;
        long resultNum = 0;
        long resultDen = 1;
        double minDifference = Double.MAX_VALUE;

        for (long denom = 1; denom <= n; ++denom) {
            double val = ratio * denom;
            long numFloor = (long) Math.floor(val);
            long numCeil = numFloor + 1;

            double diffFloor = Math.abs(ratio - (double) numFloor / denom);
            double diffCeil = Math.abs((double) numCeil / denom - ratio);

            if (diffFloor < minDifference) {
                minDifference = diffFloor;
                resultNum = numFloor;
                resultDen = denom;
            }
            if (diffCeil < minDifference) {
                minDifference = diffCeil;
                resultNum = numCeil;
                resultDen = denom;
            }
        }
        System.out.println(resultNum + "/" + resultDen);
    }
}
